// One item per overdue loan from Convex.
// Builds the message and generates the idempotent key: one reminder per loan per day.
const loan = $json;
const today = new Date().toISOString().slice(0, 10);
const days = Number(loan.daysOverdue) || 0;
const dayWord = days === 1 ? 'day' : 'days';

return {
  json: {
    loanId: loan.loanId,
    idempotencyKey: 'overdue:' + loan.loanId + ':' + today,
    to: loan.borrowerEmail || 'borrower@lendloop.local',
    toName: loan.borrowerName || 'Neighbor',
    subject: 'Reminder: please return ' + loan.toolName,
    text:
      'Hi ' + (loan.borrowerName || 'there') + ', "' + loan.toolName + '" was due on ' +
      (loan.endDate || loan.dueDate) + ' and is ' + days + ' ' + dayWord + ' overdue. ' +
      'Please return it to your neighbor as soon as you can.',
  },
};

// MOCK delivery channel (allowed by spec).
// Logs notification to n8n console.
// Protected by onError: continueErrorOutput so an individual failure never blocks the rest of the batch.
if (!$json.to) {
  throw new Error('Missing recipient for loan ' + $json.loanId);
}

const [name, domain] = String($json.to).split('@');
const masked = (name ? name[0] : '?') + '***@' + (domain || '?');

console.log(
  '[LendLoop][reminder] ' +
    JSON.stringify({
      loanId: $json.loanId,
      to: masked,
      subject: $json.subject,
    }),
);

return { json: { ...$json, channel: 'mock-log' } };

// Formats the write-back payload for Convex whether delivery succeeded or failed.
const base = $('Build reminder').item.json;
const failed = Boolean($json.error);
const reason = failed
  ? String(($json.error && $json.error.message) || $json.error).slice(0, 200)
  : 'mock-log';

return {
  json: {
    type: 'overdue_reminder',
    loanId: base.loanId,
    idempotencyKey: base.idempotencyKey,
    status: failed ? 'failed' : 'sent',
    detail: reason,
  },
};

// Asserts all items were delivered. If any failed, triggers workflow failure
// so the configured Error Trigger workflow will alert.
const prepared = $('Prepare write-back').all();
const failed = prepared.filter((item) => item.json.status === 'failed');

if (failed.length > 0) {
  throw new Error(
    failed.length + ' of ' + prepared.length + ' overdue reminders failed (loanIds: ' +
      failed.map((item) => item.json.loanId).join(', ') + ')',
  );
}

return [{ json: { ok: true, reminders: prepared.length } }];
